test("40 by 30 by 20 cm parcel weighing 3.2 kg bills the greater rounded weight of 5.0 kg", function () {
  var result = code.billableWeight({ lengthCm: 40, widthCm: 30.0, heightCm: 20, actualWeightKg: 3.2 });
  assert.equal(result.dimensionalWeightKg, 4.8);
  assert.equal(result.roundedDimensionalWeightKg, 5.0);
  assert.equal(result.roundedActualWeightKg, 3.5);
  assert.equal(result.billableWeightKg, 5.0);
});

test("10 by 10 by 10 cm parcel weighing 2.0 kg bills 2.0 kg", function () {
  var result = code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2.0 });
  assert.equal(result.dimensionalWeightKg, 0.2);
  assert.equal(result.roundedDimensionalWeightKg, 0.5);
  assert.equal(result.roundedActualWeightKg, 2.0);
  assert.equal(result.billableWeightKg, 2.0);
});

test("40 by 25 by 22 cm parcel weighing 4.1 kg bills 4.5 kg from the rounded weights not the greater raw weight", function () {
  var result = code.billableWeight({ lengthCm: 40, widthCm: 25, heightCm: 22, actualWeightKg: 4.1 });
